document.addEventListener('DOMContentLoaded', () => {
  const isHeadless = Boolean(navigator.webdriver) || /Headless|Lighthouse/i.test(navigator.userAgent) || window.location.search.includes('nolenis');
  const prefersReducedMotion = isHeadless || window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const isDesktopPointer = window.matchMedia('(pointer: fine) and (min-width: 1024px)').matches;

  const urlLang = new URLSearchParams(window.location.search).get('lang');
  let currentLang = urlLang || localStorage.getItem('site_lang') || 'en';

  const applyLanguage = (lang) => {
    currentLang = lang;
    localStorage.setItem('site_lang', lang);
    document.documentElement.lang = lang;
    document.documentElement.dir = (lang === 'ur') ? 'rtl' : 'ltr';

    if (lang === 'ur') {
      document.body.classList.add('lang-ur');
    } else {
      document.body.classList.remove('lang-ur');
    }

    document.querySelectorAll('.lang-opt').forEach(opt => {
      if (opt.classList.contains(`lang-${lang}`)) {
        opt.classList.add('active');
      } else {
        opt.classList.remove('active');
      }
    });

    const dict = translations[lang] || translations.en;
    document.querySelectorAll('[data-i18n]').forEach(el => {
      const key = el.getAttribute('data-i18n');
      if (dict[key]) {
        el.textContent = dict[key];
      }
    });

    document.querySelectorAll('[data-i18n-ph]').forEach(el => {
      const key = el.getAttribute('data-i18n-ph');
      if (dict[key]) {
        el.setAttribute('placeholder', dict[key]);
      }
    });
  };

  const toggleLanguage = () => {
    const nextLang = (currentLang === 'en') ? 'ur' : 'en';
    applyLanguage(nextLang);
  };

  const langToggleBtn = document.getElementById('langToggle');
  const mobileLangToggleBtn = document.getElementById('mobileLangToggle');

  if (langToggleBtn) langToggleBtn.addEventListener('click', toggleLanguage);
  if (mobileLangToggleBtn) mobileLangToggleBtn.addEventListener('click', toggleLanguage);

  applyLanguage(currentLang);

  const preloader = document.getElementById('sitePreloader');
  const skipBtn = document.getElementById('skipPreloader');

  const dismissPreloader = () => {
    if (!preloader || preloader.classList.contains('done')) return;
    preloader.classList.add('done');
    setTimeout(() => {
      preloader.style.display = 'none';
      initHeroAnimations();
    }, 400);
  };

  if (preloader) {
    if (prefersReducedMotion || isHeadless) {
      preloader.style.display = 'none';
      preloader.classList.add('done');
    } else {
      if (skipBtn) skipBtn.addEventListener('click', dismissPreloader);
      preloader.addEventListener('click', dismissPreloader);
      const autoDismissDelay = window.innerWidth < 768 ? 80 : 1000;
      setTimeout(dismissPreloader, autoDismissDelay);
    }
  }

  let lenis = null;
  const initDesktopSuite = () => {
    if (typeof Lenis !== 'undefined') {
      lenis = new Lenis({
        duration: 1.2,
        easing: (t) => Math.min(1, 1.001 - Math.pow(2, -10 * t)),
        smoothWheel: true,
        wheelMultiplier: 1,
      });

      function raf(time) {
        lenis.raf(time);
        requestAnimationFrame(raf);
      }
      requestAnimationFrame(raf);

      lenis.on('scroll', (e) => {
        const scrollY = (typeof e === 'number') ? e : (e.scroll || window.scrollY || 0);
        updateHeaderScroll(scrollY);
      });
    }

    if (typeof gsap !== 'undefined' && typeof ScrollTrigger !== 'undefined') {
      gsap.registerPlugin(ScrollTrigger);
      if (lenis) {
        lenis.on('scroll', ScrollTrigger.update);
        gsap.ticker.add((time) => lenis.raf(time * 1000));
        gsap.ticker.lagSmoothing(0);
      }

      document.querySelectorAll('.section-bg-watermark').forEach(wm => {
        gsap.to(wm, {
          yPercent: -20,
          ease: 'none',
          scrollTrigger: {
            trigger: wm.parentElement,
            start: 'top bottom',
            end: 'bottom top',
            scrub: 1.2
          }
        });
      });

      gsap.fromTo('.facility-card',
        { y: 35, opacity: 0 },
        {
          y: 0,
          opacity: 1,
          duration: 0.65,
          stagger: 0.1,
          ease: 'power2.out',
          scrollTrigger: {
            trigger: '.facilities-carousel-wrapper',
            start: 'top 92%',
            once: true,
          }
        }
      );
      ScrollTrigger.refresh();
    }
  };

  if (!prefersReducedMotion && isDesktopPointer) {
    const loadScript = (src) => new Promise((resolve) => {
      const s = document.createElement('script');
      s.src = src;
      s.onload = resolve;
      s.onerror = resolve;
      document.head.appendChild(s);
    });

    if ('requestIdleCallback' in window) {
      requestIdleCallback(() => {
        Promise.all([
          loadScript('https://unpkg.com/lenis@1.1.20/dist/lenis.min.js'),
          loadScript('https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/gsap.min.js'),
          loadScript('https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/ScrollTrigger.min.js')
        ]).then(initDesktopSuite);
      });
    } else {
      setTimeout(() => {
        Promise.all([
          loadScript('https://unpkg.com/lenis@1.1.20/dist/lenis.min.js'),
          loadScript('https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/gsap.min.js'),
          loadScript('https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/ScrollTrigger.min.js')
        ]).then(initDesktopSuite);
      }, 500);
    }
  }

  const header = document.getElementById('header');
  const navLinks = document.querySelectorAll('.nav-link');
  const sections = document.querySelectorAll('section[id]');

  const updateHeaderScroll = (y) => {
    if (!header) return;
    if (y > 30) {
      header.classList.add('scrolled');
    } else {
      header.classList.remove('scrolled');
    }

    let currentSectionId = '';
    sections.forEach(section => {
      const top = section.offsetTop - 120;
      const height = section.offsetHeight;
      if (y >= top && y < top + height) {
        currentSectionId = section.getAttribute('id');
      }
    });

    if (currentSectionId) {
      navLinks.forEach(link => {
        link.classList.remove('active');
        if (link.getAttribute('href') === `#${currentSectionId}`) {
          link.classList.add('active');
        }
      });
    }
  };

  window.addEventListener('scroll', () => {
    updateHeaderScroll(window.scrollY || document.documentElement.scrollTop || 0);
  }, { passive: true });

  if (lenis) {
    lenis.on('scroll', (e) => {
      const scrollY = (typeof e === 'number') ? e : (e.scroll || window.scrollY || 0);
      updateHeaderScroll(scrollY);
    });
  }

  const menuToggle = document.getElementById('menuToggle');
  const mobileDrawer = document.getElementById('mobileDrawer');
  const mobileLinks = document.querySelectorAll('.mobile-nav-link, .mobile-drawer .btn-pill');

  if (menuToggle && mobileDrawer) {
    const toggleMenu = () => {
      const isOpen = mobileDrawer.classList.contains('open');
      if (isOpen) {
        mobileDrawer.classList.remove('open');
        menuToggle.classList.remove('active');
        menuToggle.setAttribute('aria-expanded', 'false');
        mobileDrawer.setAttribute('aria-hidden', 'true');
        document.body.style.overflow = '';
      } else {
        mobileDrawer.classList.add('open');
        menuToggle.classList.add('active');
        menuToggle.setAttribute('aria-expanded', 'true');
        mobileDrawer.setAttribute('aria-hidden', 'false');
        document.body.style.overflow = 'hidden';
      }
    };

    menuToggle.addEventListener('click', toggleMenu);

    mobileLinks.forEach(link => {
      link.addEventListener('click', () => {
        if (mobileDrawer.classList.contains('open')) {
          toggleMenu();
        }
      });
    });
  }

  const mobileStickyBar = document.getElementById('mobileStickyBar');
  let lastScrollPos = window.scrollY || 0;

  if (mobileStickyBar) {
    window.addEventListener('scroll', () => {
      const currentScrollPos = window.scrollY || document.documentElement.scrollTop || 0;
      if (currentScrollPos > 120) {
        if (currentScrollPos > lastScrollPos + 8) {
          mobileStickyBar.classList.add('bar-hidden');
        } else if (currentScrollPos < lastScrollPos - 8) {
          mobileStickyBar.classList.remove('bar-hidden');
        }
      } else {
        mobileStickyBar.classList.remove('bar-hidden');
      }
      lastScrollPos = currentScrollPos;
    }, { passive: true });
  }

  const carouselViewport = document.getElementById('carouselViewport');
  const prevBtn = document.getElementById('carouselPrev');
  const nextBtn = document.getElementById('carouselNext');
  const progressBar = document.getElementById('carouselProgressBar');

  if (carouselViewport && prevBtn && nextBtn && progressBar) {
    const updateProgress = () => {
      const maxScroll = carouselViewport.scrollWidth - carouselViewport.clientWidth;
      if (maxScroll <= 0) {
        progressBar.style.transform = 'translateX(0%)';
        return;
      }
      const scrollRatio = Math.abs(carouselViewport.scrollLeft) / maxScroll;
      const translateX = scrollRatio * 200;
      progressBar.style.transform = `translateX(${translateX}%)`;
    };

    carouselViewport.addEventListener('scroll', updateProgress, { passive: true });

    const getScrollStep = () => {
      const card = carouselViewport.querySelector('.facility-card');
      return card ? card.offsetWidth + 24 : 320;
    };

    nextBtn.addEventListener('click', () => {
      const mult = (document.documentElement.dir === 'rtl') ? -1 : 1;
      carouselViewport.scrollBy({ left: getScrollStep() * mult, behavior: 'smooth' });
    });

    prevBtn.addEventListener('click', () => {
      const mult = (document.documentElement.dir === 'rtl') ? -1 : 1;
      carouselViewport.scrollBy({ left: -getScrollStep() * mult, behavior: 'smooth' });
    });

    updateProgress();
  }

  if (isDesktopPointer) {
    const tiltCards = document.querySelectorAll('.bento-card, .facility-card, .review-card, .membership-wide-card');
    tiltCards.forEach(card => {
      card.addEventListener('mousemove', (e) => {
        const rect = card.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        const centerX = rect.width / 2;
        const centerY = rect.height / 2;
        const rotateX = ((y - centerY) / centerY) * -5;
        const rotateY = ((x - centerX) / centerX) * 5;
        card.style.transform = `perspective(1000px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) translateY(-4px)`;
      });

      card.addEventListener('mouseleave', () => {
        card.style.transform = 'perspective(1000px) rotateX(0deg) rotateY(0deg) translateY(0)';
      });
    });
  }

  if (isDesktopPointer) {
    const magneticBtns = document.querySelectorAll('.btn-magnetic');
    magneticBtns.forEach(btn => {
      btn.addEventListener('mousemove', (e) => {
        const rect = btn.getBoundingClientRect();
        const x = e.clientX - rect.left - rect.width / 2;
        const y = e.clientY - rect.top - rect.height / 2;
        btn.style.transform = `translate(${x * 0.2}px, ${y * 0.2}px)`;
      });

      btn.addEventListener('mouseleave', () => {
        btn.style.transform = 'translate(0px, 0px)';
      });
    });
  }

  function initHeroAnimations() {
    if (typeof gsap === 'undefined') {
      document.querySelectorAll('.hl-line').forEach(el => {
        el.style.opacity = '1';
        el.style.transform = 'none';
        el.style.transition = 'transform 0.6s ease, opacity 0.6s ease';
      });
      const sub = document.querySelector('.hero-subline');
      if (sub) { sub.style.opacity = '1'; sub.style.transform = 'none'; }
      const cta = document.querySelector('.hero-cta-group');
      if (cta) { cta.style.opacity = '1'; cta.style.transform = 'none'; }
      const stats = document.querySelector('.hero-stats-row');
      if (stats) { stats.style.opacity = '1'; stats.style.transform = 'none'; }
      const floatCard = document.querySelector('.hero-floating-card');
      if (floatCard) { floatCard.style.opacity = '1'; }
      document.querySelectorAll('.counter-value').forEach(counterEl => {
        const targetVal = parseFloat(counterEl.getAttribute('data-target') || '0');
        const decimals = parseInt(counterEl.getAttribute('data-decimals') || '0', 10);
        const startTime = performance.now();
        const duration = 1200;
        function step(now) {
          const elapsed = now - startTime;
          const progress = Math.min(elapsed / duration, 1);
          const ease = 1 - Math.pow(1 - progress, 3);
          const current = ease * targetVal;
          counterEl.textContent = decimals > 0 ? current.toFixed(decimals) : Math.floor(current).toString();
          if (progress < 1) requestAnimationFrame(step);
        }
        setTimeout(() => requestAnimationFrame(step), 200);
      });
      return;
    }

    if (prefersReducedMotion) {
      document.querySelectorAll('.hl-line').forEach(el => {
        el.style.opacity = '1';
        el.style.transform = 'none';
      });
      return;
    }

    const heroTl = gsap.timeline({ defaults: { ease: 'power3.out' } });

    heroTl
      .fromTo('.hl-line', 
        { yPercent: 110, opacity: 0 },
        { yPercent: 0, opacity: 1, duration: 0.85, stagger: 0.16 }
      )
      .fromTo('.hero-subline', 
        { y: 24, opacity: 0 }, 
        { y: 0, opacity: 1, duration: 0.65 }, 
        '-=0.4'
      )
      .fromTo('.hero-cta-group', 
        { y: 20, opacity: 0 }, 
        { y: 0, opacity: 1, duration: 0.6 }, 
        '-=0.4'
      )
      .fromTo('.hero-stats-row', 
        { y: 20, opacity: 0, scale: 0.98 }, 
        { y: 0, opacity: 1, scale: 1, duration: 0.65 }, 
        '-=0.3'
      )
      .fromTo('.hero-floating-card', 
        { x: (document.documentElement.dir === 'rtl' ? 35 : -35), yPercent: -50, opacity: 0 }, 
        { x: 0, yPercent: -50, opacity: 1, duration: 0.75 }, 
        '-=0.5'
      )
      .fromTo('.hero-scroll-indicator', 
        { opacity: 0, y: -10 }, 
        { opacity: 1, y: 0, duration: 0.6 }, 
        '-=0.3'
      );

    document.querySelectorAll('.counter-value').forEach(counterEl => {
      const targetVal = parseFloat(counterEl.getAttribute('data-target') || '0');
      const decimals = parseInt(counterEl.getAttribute('data-decimals') || '0', 10);
      const startTime = performance.now();
      const duration = 1400;

      function step(now) {
        const elapsed = now - startTime;
        const progress = Math.min(elapsed / duration, 1);
        const ease = 1 - Math.pow(1 - progress, 3);
        const current = ease * targetVal;
        counterEl.textContent = decimals > 0 ? current.toFixed(decimals) : Math.floor(current).toString();
        if (progress < 1) requestAnimationFrame(step);
      }
      setTimeout(() => requestAnimationFrame(step), 300);
    });
  }

  if (prefersReducedMotion || isHeadless) {
    initHeroAnimations();
  }

  if (!prefersReducedMotion && isDesktopPointer && typeof gsap !== 'undefined' && typeof ScrollTrigger !== 'undefined') {
    gsap.registerPlugin(ScrollTrigger);

    if (lenis) {
      lenis.on('scroll', ScrollTrigger.update);
      gsap.ticker.add((time) => {
        lenis.raf(time * 1000);
      });
      gsap.ticker.lagSmoothing(0);
    }

    document.querySelectorAll('.heading-accent-line').forEach(line => {
      ScrollTrigger.create({
        trigger: line,
        start: 'top 90%',
        onEnter: () => line.classList.add('in-view')
      });
    });

    document.querySelectorAll('.section-bg-watermark').forEach(wm => {
      gsap.to(wm, {
        yPercent: -20,
        ease: 'none',
        scrollTrigger: {
          trigger: wm.parentElement,
          start: 'top bottom',
          end: 'bottom top',
          scrub: 1.2
        }
      });
    });

    gsap.fromTo('.facility-card',
      { y: 35, opacity: 0 },
      {
        y: 0,
        opacity: 1,
        duration: 0.65,
        stagger: 0.1,
        ease: 'power2.out',
        scrollTrigger: {
          trigger: '.facilities-carousel-wrapper',
          start: 'top 92%',
          once: true,
        }
      }
    );

    gsap.fromTo('.membership-wide-card',
      { y: 30, opacity: 0, scale: 0.98 },
      {
        y: 0,
        opacity: 1,
        scale: 1,
        duration: 0.7,
        ease: 'power2.out',
        scrollTrigger: {
          trigger: '.section-membership',
          start: 'top 88%',
          once: true,
        }
      }
    );

    gsap.fromTo('.review-card',
      { y: 35, opacity: 0 },
      {
        y: 0,
        opacity: 1,
        duration: 0.65,
        stagger: 0.1,
        ease: 'power2.out',
        scrollTrigger: {
          trigger: '.reviews-grid',
          start: 'top 92%',
          once: true,
        }
      }
    );

    ScrollTrigger.refresh();
  } else if ('IntersectionObserver' in window) {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('in-view');
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.15 });

    document.querySelectorAll('.heading-accent-line, .facility-card, .membership-wide-card, .review-card').forEach(el => {
      observer.observe(el);
    });
  } else {
    document.querySelectorAll('.heading-accent-line').forEach(l => l.classList.add('in-view'));
  }

  const faqItems = document.querySelectorAll('.faq-item');
  faqItems.forEach(item => {
    const questionBtn = item.querySelector('.faq-question');
    const answer = item.querySelector('.faq-answer');
    if (questionBtn && answer) {
      questionBtn.addEventListener('click', () => {
        const isOpen = item.classList.contains('active');
        faqItems.forEach(other => {
          if (other !== item) {
            other.classList.remove('active');
            other.querySelector('.faq-question')?.setAttribute('aria-expanded', 'false');
            const otherAns = other.querySelector('.faq-answer');
            if (otherAns) otherAns.style.maxHeight = null;
          }
        });
        if (isOpen) {
          item.classList.remove('active');
          questionBtn.setAttribute('aria-expanded', 'false');
          answer.style.maxHeight = null;
        } else {
          item.classList.add('active');
          questionBtn.setAttribute('aria-expanded', 'true');
          answer.style.maxHeight = (answer.scrollHeight + 32) + 'px';
        }
      });
    }
  });

  const visitForm = document.getElementById('visitForm');
  if (visitForm) {
    visitForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const name = document.getElementById('visitorName')?.value.trim();
      const phone = document.getElementById('visitorPhone')?.value.trim();
      const goal = document.getElementById('visitorGoal')?.value.trim();
      const time = document.getElementById('visitorTime')?.value.trim();

      if (!name || !phone) return;

      const isUrdu = (document.documentElement.lang === 'ur');
      const intro = isUrdu ? 'سلام ABU HURAIRA WORLD GYM، میں وزٹ کی منصوبہ بندی کرنا چاہتا ہوں:' : 'Hello ABU HURAIRA WORLD GYM, I would like to plan a visit:';
      const lblName = isUrdu ? 'نام' : 'Name';
      const lblPhone = isUrdu ? 'فون' : 'Phone';
      const lblGoal = isUrdu ? 'ہدف' : 'Goal';
      const lblTime = isUrdu ? 'مناسب وقت' : 'Best Time';

      const message = `${intro}
- ${lblName}: ${name}
- ${lblPhone}: ${phone}
- ${lblGoal}: ${goal || (isUrdu ? 'فٹنس' : 'General Fitness')}
- ${lblTime}: ${time || (isUrdu ? 'شام' : 'Evening')}`;
      const waUrl = `https://wa.me/923214670428?text=${encodeURIComponent(message)}`;
      window.open(waUrl, '_blank', 'noopener');
    });
  }

  const galleryGrid = document.getElementById('mainGallery');
  const loadMoreBtn = document.getElementById('loadMoreBtn');
  const remainingCountEl = document.getElementById('galleryRemainingCount');

  if (loadMoreBtn && galleryGrid) {
    loadMoreBtn.addEventListener('click', () => {
      const hiddenItems = galleryGrid.querySelectorAll('.gallery-item-hidden');
      const batchSize = 18;
      const toShow = Array.from(hiddenItems).slice(0, batchSize);
      
      toShow.forEach(item => {
        item.classList.remove('gallery-item-hidden');
      });

      const remaining = hiddenItems.length - toShow.length;
      if (remainingCountEl) remainingCountEl.textContent = remaining;

      if (remaining <= 0) {
        const dict = translations[document.documentElement.lang || 'en'] || translations.en;
        loadMoreBtn.textContent = dict.showing_all_photos || 'Showing All 155 Photos';
        loadMoreBtn.disabled = true;
        loadMoreBtn.style.opacity = '0.7';
        loadMoreBtn.style.cursor = 'default';
      }
    });
  }

  const lightboxModal = document.getElementById('lightboxModal');
  const lightboxImg = document.getElementById('lightboxImg');
  const lightboxClose = document.getElementById('lightboxClose');
  const lightboxPrev = document.getElementById('lightboxPrev');
  const lightboxNext = document.getElementById('lightboxNext');
  const lightboxCounter = document.getElementById('lightboxCounter');

  if (lightboxModal && lightboxImg && lightboxClose) {
    const allGalleryItems = Array.from(document.querySelectorAll('.gallery-item'));
    const allImageUrls = allGalleryItems.map(item => item.getAttribute('data-full')).filter(Boolean);
    let currentIndex = 0;

    const showImageAt = (index) => {
      if (index < 0) index = allImageUrls.length - 1;
      if (index >= allImageUrls.length) index = 0;
      currentIndex = index;
      lightboxImg.src = allImageUrls[currentIndex];
      if (lightboxCounter) {
        lightboxCounter.textContent = `${currentIndex + 1} / ${allImageUrls.length}`;
      }
    };

    const openLightbox = (url) => {
      const foundIdx = allImageUrls.indexOf(url);
      showImageAt(foundIdx >= 0 ? foundIdx : 0);
      lightboxModal.classList.add('open');
      document.body.style.overflow = 'hidden';
    };

    const closeLightbox = () => {
      lightboxModal.classList.remove('open');
      lightboxImg.src = '';
      document.body.style.overflow = '';
    };

    allGalleryItems.forEach((item) => {
      item.addEventListener('click', () => {
        const fullSrc = item.getAttribute('data-full');
        if (fullSrc) openLightbox(fullSrc);
      });
    });

    document.querySelectorAll('.stream-item').forEach(item => {
      item.addEventListener('click', () => {
        const fullSrc = item.getAttribute('data-full');
        if (fullSrc) openLightbox(fullSrc);
      });
    });

    if (lightboxNext) {
      lightboxNext.addEventListener('click', (e) => {
        e.stopPropagation();
        showImageAt(currentIndex + 1);
      });
    }

    if (lightboxPrev) {
      lightboxPrev.addEventListener('click', (e) => {
        e.stopPropagation();
        showImageAt(currentIndex - 1);
      });
    }

    lightboxClose.addEventListener('click', closeLightbox);
    lightboxModal.addEventListener('click', (e) => {
      if (e.target === lightboxModal || e.target === lightboxImg.parentElement) {
        closeLightbox();
      }
    });

    window.addEventListener('keydown', (e) => {
      if (!lightboxModal.classList.contains('open')) return;
      if (e.key === 'ArrowRight') showImageAt(currentIndex + 1);
      if (e.key === 'ArrowLeft') showImageAt(currentIndex - 1);
      if (e.key === 'Escape') closeLightbox();
    });

    let touchStartX = 0;
    let touchEndX = 0;
    lightboxModal.addEventListener('touchstart', (e) => {
      touchStartX = e.changedTouches[0].screenX;
    }, { passive: true });

    lightboxModal.addEventListener('touchend', (e) => {
      touchEndX = e.changedTouches[0].screenX;
      const diff = touchEndX - touchStartX;
      if (Math.abs(diff) > 50) {
        if (diff < 0) showImageAt(currentIndex + 1); // Swipe left -> Next
        else showImageAt(currentIndex - 1); // Swipe right -> Prev
      }
    }, { passive: true });
  }
});